import './Auth.css';
import { useSelector, useDispatch } from 'react-redux';
import { locationActions, authActions } from '../store/index';
import { locations } from "../data";

function Auth() {
    const dispatch = useDispatch();
    const selectedLocation = useSelector(state => state.location.selectedLocation);

    const handleLocationChange = (event) => {
        const selectedValue = event.target.value;
        const selectedLocation = locations.find(loc => loc.value === selectedValue || loc.label === selectedValue);
        if (selectedLocation) {
            dispatch(locationActions.updateLocation(selectedLocation.value));
        }
    }

    const loginHandler = (event) => {
        event.preventDefault();
        dispatch(authActions.login());
    }

    return (
        <main>
            <section>
                <form onSubmit={loginHandler}>
                    <label htmlFor='location'>Location</label>
                    <div className="select-wrapper">
                        <input
                            list="locations"
                            id="location"
                            name="location"
                            value={selectedLocation}
                            onChange={handleLocationChange}
                            className="select-input"
                        />
                        <datalist id="locations">
                            {locations.map(location => (
                                <option key={location.value} value={location.value}>
                                    {location.label}
                                </option>
                            ))}
                        </datalist>
                    </div>
                    <label htmlFor='password'>Password</label>
                    <input type='password' id='password' />
                    <button className='button'>Login</button>
                </form>
            </section>
        </main>
    );
}

export default Auth;
